/* POSH Inquiry Navigator — integrated Alpha 3.1 fictional guided workflow.
   Client-only; no real case data, server requests, legal decisions or authoritative service dates.
   All actions are educational synthetic choices requiring independent legal review. */
(()=>{'use strict';
const Q=[
['P01','What was received by the competent committee?','written|Written|P02;oral_needs_assistance|Oral complaint needing writing assistance|HUMAN_RECEIPT_REVIEW;incomplete|Incomplete written complaint|HUMAN_RECEIPT_REVIEW;unknown|Not known|FACT_UNCERTAINTY_REVIEW','Section 9; Rule 6 assistance and applicable complaint procedure'],
['P02','Which chronology best describes the alleged incidents?','single_within_3_months|Single incident within the ordinary period|P03;series_of_incidents|Series of incidents|P03;late_or_disputed_dates|Possibly late or disputed dates|HUMAN_LIMITATION_REVIEW;unknown|Not known|HUMAN_LIMITATION_REVIEW','Section 9 limitation and reasoned extension'],
['P03','Which workplace relationship is alleged?','employee|Employee|P04;former_employee|Former employee|P04;nonemployee_or_visitor|Non-employee or visitor|P04;student_or_minor|Student or minor|SPECIAL_JURISDICTION_REVIEW;unclear|Unclear|SPECIAL_JURISDICTION_REVIEW','Sections 2 and 3; relevant institutional and child-protection duties'],
['P04','What is the respondent’s workplace relationship?','same_organisation|Same organisation|P05;different_organisation|Different employer or workplace|SPECIAL_JURISDICTION_REVIEW;employer_or_senior_management|Employer or senior management|SPECIAL_JURISDICTION_REVIEW;outsider|External person|P05;unknown|Not known|SPECIAL_JURISDICTION_REVIEW','Section 6 and jurisdiction-specific competence'],
['P05','Which forum is being considered?','ic|Internal Committee (IC)|P06;lc|Local Committee (LC)|P06;committee_missing|No committee available|COMMITTEE_CORRECTION_REVIEW;disputed|Committee jurisdiction disputed|COMMITTEE_CORRECTION_REVIEW;unknown|Unknown|COMMITTEE_CORRECTION_REVIEW','Sections 4 and 6; appropriate IC/LC jurisdiction'],
['P06','Does the committee satisfy constitution and independence requirements?','valid|Valid composition and tenure reviewed|P07;expired_or_vacancy|Expired order or vacancy|COMMITTEE_CORRECTION_REVIEW;conflict_or_recusal|Conflict or recusal issue|COMMITTEE_CORRECTION_REVIEW;unknown|Not verified|COMMITTEE_CORRECTION_REVIEW','Section 4; committee conflicts and applicable participation rules'],
['P07','How does the alleged conduct relate to sexual harassment?','specific_2n_conduct|Potential Section 2(n) conduct|P08;3_2_circumstances_with_2n|Section 3(2) circumstances with Section 2(n) conduct|P08;nonposh_grievance|Other workplace grievance without apparent sexual element|ALLEGATION_SCOPE_REVIEW;mixed_or_unclear|Mixed or unclear allegations|ALLEGATION_SCOPE_REVIEW','Section 2(n) definition; Section 3(2) circumstances'],
['P08','Are material complaint particulars missing?','complete|Particulars sufficiently identified|P09;needs_dates_or_particulars|Dates or facts require clarification|HUMAN_RECEIPT_REVIEW;needs_documents|Relevant supporting materials to clarify|HUMAN_RECEIPT_REVIEW;unclear|Completeness uncertain|HUMAN_RECEIPT_REVIEW','Section 9, neutral clarification and non-leading assistance'],
['P09','Is there a confidentiality, intimidation or protection concern?','none|No specific concern identified|P10;disclosure_risk|Confidentiality / disclosure risk|P10;retaliation_risk|Retaliation or pressure risk|P10;urgent_safety|Urgent safety concern|P10;unknown|Unknown|FACT_UNCERTAINTY_REVIEW','Sections 12 and 16; lawful protective steps; urgent assistance independently'],
['P10','Has the committee documented preliminary procedural decisions?','recorded|Relevant decisions and reasons recorded|P11;needs_meeting|Preliminary meeting required|HUMAN_PRELIMINARY_REVIEW;constitution_issue|Committee constitution issue|HUMAN_PRELIMINARY_REVIEW;unknown|Not verified|HUMAN_PRELIMINARY_REVIEW','Section 11 and applicable committee procedure'],
['P11','Did the aggrieved woman request conciliation before inquiry began?','yes_written|Yes, voluntary written request|P12;yes_oral_needs_confirmation|Requested orally, requires verification|CONCILIATION_CONSENT_REVIEW;no|No request|P13;respondent_only|Only respondent/employer requested it|P13;already_inquiry|Inquiry already began|P13;unknown|Not known|FACT_UNCERTAINTY_REVIEW','Section 10: only on aggrieved woman’s request before inquiry; no monetary basis'],
['P12','What occurred in the lawful conciliation route?','settlement_recorded|Settlement recorded|SETTLEMENT_CLOSURE_REVIEW;no_agreement|No agreement reached|P13;settlement_breached|Settlement not complied with|SETTLEMENT_BREACH_ROUTE;withdrawn_or_unclear|Withdrawal or voluntariness unclear|CONCILIATION_CONSENT_REVIEW','Sections 10 and 11; implementation or breach pathway'],
['P13','What is the status of forwarding the complaint to the respondent?','not_prepared|Notice not prepared|NOTICE_PREPARATION_REVIEW;sent_with_copy|Complaint and required materials forwarded|P14;sent_without_required_material|Sent but required materials missing|NOTICE_PREPARATION_REVIEW;unknown|Dispatch uncertain|NOTICE_PREPARATION_REVIEW','Rule 7(2) only where applicable; preserve proof of dispatch and receipt'],
['P14','What happened to the notice?','served|Receipt established|P15;refused|Recipient refused delivery|SERVICE_PROOF_REVIEW;undelivered|Undelivered|SERVICE_PROOF_REVIEW;service_disputed|Electronic or other service disputed|SERVICE_PROOF_REVIEW;unknown|Unknown status|SERVICE_PROOF_REVIEW','Actual service, receipt evidence and governing rules; disputed service is not a receipt date'],
['P15','What is the reply status?','received_in_time|Reply received within applicable period|P16;late|Reply received late|LATE_REPLY_REVIEW;extension_requested|Extension of time requested|REPLY_OPPORTUNITY_REVIEW;no_reply|No reply received|REPLY_OPPORTUNITY_REVIEW;unknown|Reply status unknown|REPLY_OPPORTUNITY_REVIEW','Rule 7(3) ten working days if applicable; no reply is not an admission'],
['P16','How does the respondent answer each allegation?','full_admission|Complete admission stated|P17;qualified_or_partial_admission|Qualified or partial admission|P17;complete_denial|Complete denial|P17;mixed|Mixture of admissions and denials|P17;no_response|No written response|REPLY_OPPORTUNITY_REVIEW','Allegation-wise fact recording; an admission of words is not automatically admission of misconduct'],
['P17','Has any party raised a procedural objection?','none|No material procedural objection identified|P18;jurisdiction_or_limitation|Jurisdiction or limitation objection|OBJECTION_REASONING_REVIEW;bias_or_disclosure|Bias, disclosure or fairness objection|OBJECTION_REASONING_REVIEW;other|Other material objection|OBJECTION_REASONING_REVIEW','Competent committee must record and reason through material objections']
].map(([id,prompt,opts,law])=>({id,prompt,law,opts:opts.split(';').map(s=>{let [value,label,next]=s.split('|');return {value,label,next}})}));
const RULES={
HUMAN_RECEIPT_REVIEW:['Complaint clarification or assistance','Missing particulars need neutral clarification; an incomplete complaint is not automatically rejected.','Identify factual gaps without coaching allegations.;Offer writing assistance where the applicable rules permit.;Record outstanding particulars and steps already taken.','conditions_verified|Particulars and assistance reviewed|NEXT'],
HUMAN_LIMITATION_REVIEW:['Limitation assessment','Check actual dates and any legally permitted Section 9 extension.','Identify incident date or last incident of a series.;Verify limitation and potential permitted extension.;Have the competent committee record reasons and decision.','within_period|Within applicable period|NEXT;extension_reviewed|Lawful, reasoned extension determined|NEXT'],
SPECIAL_JURISDICTION_REVIEW:['Special jurisdiction and duties','Some relationships call for a different competent forum or separate duties.','Identify the legally competent IC/LC or other authority.;Assess employer, student, cross-employer or domestic-worker rules.;Assess POCSO/child-protection duties separately where relevant.','conditions_verified|Competent forum and duties verified|NEXT;external_referral|Refer to competent authority|OUTCOME'],
COMMITTEE_CORRECTION_REVIEW:['Committee validity or jurisdiction','Missing, expired, conflicted or disputed committees cannot simply assume competence.','Verify constitution order, membership, tenure and jurisdiction.;Resolve vacancies, recusal or conflicts lawfully.;Document the reasoned correction or proper referral.','conditions_verified|Legally competent committee established|NEXT;jurisdictional_referral|Refer for competent forum assessment|OUTCOME'],
ALLEGATION_SCOPE_REVIEW:['Allegation scope and mixed grievances','Section 3(2) circumstances do not independently establish sexual harassment without the applicable sexual conduct.','Distinguish Section 2(n) allegations from other workplace issues.;Keep mixed grievances separate without inventing facts.;Record if another complaint mechanism is more appropriate.','conditions_verified|POSH component identified; other issues separated|NEXT;other_grievance_route|Use appropriate non-POSH grievance process|OUTCOME'],
HUMAN_PRELIMINARY_REVIEW:['Preliminary committee record','The software cannot invent a committee meeting or procedural decision.','Verify relevant committee participation.;Document actual decisions, reasons and pending procedural requirements.','conditions_verified|Preliminary record complete|NEXT'],
CONCILIATION_CONSENT_REVIEW:['Section 10 request and consent','Only a voluntary request by the aggrieved woman before inquiry can authorise conciliation under Section 10.','Check voluntary aggrieved woman request.;Confirm inquiry has not begun.;No monetary settlement as the basis and no coercion.','voluntary_request|Eligible voluntary request confirmed|CONCILIATION;no_request|No eligible request — continue without conciliation|NOTICE'],
SETTLEMENT_CLOSURE_REVIEW:['Conciliation settlement and follow-up','A lawful settlement leads to statutory implementation/closure guidance, not automatic normal inquiry continuation.','Check lawful terms, voluntariness and written record.;Confirm appropriate forwarding and copies.;Track implementation and any subsequent non-compliance.','settlement_recorded|Settlement recorded — show closure/implementation route|OUTCOME'],
SETTLEMENT_BREACH_ROUTE:['Conciliation non-compliance','Non-compliance with a Section 10 settlement requires competent review of subsequent statutory routes.','Review settlement and non-compliance facts.;Document the competent authority’s selected permissible route.','breach_and_inquiry|Breach verified; inquiry route lawfully chosen|NOTICE;breach_referral|Alternative statutory referral selected|OUTCOME'],
NOTICE_PREPARATION_REVIEW:['Notice drafting and dispatch','A draft notice or incomplete dispatch cannot be treated as proof of receipt.','Confirm applicable rules and lawful service mode.;Check required complaint copy and enclosures.;Record actual dispatch separately from established receipt.','conditions_verified|Correct notice dispatched|NEXT'],
SERVICE_PROOF_REVIEW:['Notice service verification','Refused, undelivered and disputed electronic delivery need different evidence checks.','Assess how and what was served, and actual proof.;For refusal, obtain governing-rule legal review.;Do not invent a deemed service date or start a reply period without evidence.','fresh_receipt|Fresh service and receipt verified|NEXT;refusal_reviewed|Refusal independently reviewed as lawful service|NEXT'],
REPLY_OPPORTUNITY_REVIEW:['No reply or outstanding opportunity','No reply is not an admission; ex-parte hearing safeguards are a separate issue.','Verify the required materials and actual receipt date.;Check applicable reply period and any extension request.;Ensure reasoned fair opportunity; Rule 7(5) safeguards are separate.','opportunity_complete|Opportunity completed; proceed without treating silence as proof|NO_REPLY;reply_received|Reply actually received|REPLY_RECEIVED'],
LATE_REPLY_REVIEW:['Late reply procedural review','A late reply does not by itself prove allegations or erase fairness obligations.','Verify applicable period and actual receipt.;Consider the explanation and fair opportunity.;Record the competent committee’s reasoned decision.','reply_accepted|Late reply accepted after review|REPLY_RECEIVED;reply_not_accepted|Reply not accepted after fair review|NO_REPLY'],
OBJECTION_REASONING_REVIEW:['Procedural objection and remedy','Material objections require a reasoned response, not silent dismissal.','Identify and document the particular objection.;Consider lawful recusal, disclosure or correction.;Document competent reasoned determination.','conditions_verified|Objection addressed or lawfully remedied|NEXT;external_review|Independent legal or competent-authority review|OUTCOME'],
FACT_UNCERTAINTY_REVIEW:['Unknown essential fact','Unknown facts cannot be silently treated as confirmed; correct the source answer here.','Identify exactly which information is unknown.;Seek reliable clarification without filling gaps by assumption.','fact_clarified|Clarification obtained — amend original answer|EDIT']
};
const REV=Object.fromEntries(Object.entries(RULES).map(([id,[title,issue,checks,actions]])=>[id,{id,title,issue,checks:checks.split(';'),actions:actions.split(';').map(s=>{const [id,label,target]=s.split('|');return{id,label,target}})}]));
const DEFAULT={P01:'written',P02:'single_within_3_months',P03:'employee',P04:'same_organisation',P05:'ic',P06:'valid',P07:'specific_2n_conduct',P08:'complete',P09:'none',P10:'recorded',P11:'no',P13:'sent_with_copy',P14:'served',P15:'received_in_time',P16:'complete_denial',P17:'none'};
const EXAMPLES=[
['manual','Start from the beginning','P01',{}],
['no_reply','No written reply','P15',{P15:'no_reply'}],
['notice_refused','Refusal of notice','P14',{P14:'refused'}],
['notice_undelivered','Undelivered notice','P14',{P14:'undelivered'}],
['electronic_service_disputed','Electronic service disputed','P14',{P14:'service_disputed'}],
['jurisdiction_concern','Jurisdiction disputed','P05',{P05:'disputed'}],
['limitation_concern','Limitation concern','P02',{P02:'late_or_disputed_dates'}],
['incomplete_complaint','Incomplete complaint','P01',{P01:'incomplete'}],
['complete_admission','Complete admission','P16',{P16:'full_admission'}],
['complete_denial','Complete denial','P16',{P16:'complete_denial'}],
['partial_admission','Partial admission','P16',{P16:'qualified_or_partial_admission'}],
['employer_respondent','Employer named as respondent','P04',{P04:'employer_or_senior_management'}],
['conciliation_requested','Conciliation requested','P12',{P11:'yes_written',P12:'no_agreement'}],
['respondent_only_conciliation','Respondent asks for conciliation','P11',{P11:'respondent_only'}]
];
const $=id=>document.getElementById(id),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let answers={},decisions={},questionTrace=[],status='no',chosenAction='',checked=new Set(),lastKey='',outcome=null;
function nextOf(target,stage){if(target==='NEXT')return 'P'+String(Number(stage.slice(1))+1).padStart(2,'0');if(target==='NOTICE')return 'P13';if(target==='CONCILIATION')return 'P12';if(target==='NO_REPLY')return 'P17';if(target==='REPLY_RECEIVED')return 'P16';return null}
function validActions(r,stage,value){return r.actions.filter(a=>!(r.id==='ALLEGATION_SCOPE_REVIEW'&&value==='nonposh_grievance'&&a.id==='conditions_verified')&&!(r.id==='CONCILIATION_CONSENT_REVIEW'&&stage==='P12'&&a.id==='voluntary_request')&&!(r.id==='SERVICE_PROOF_REVIEW'&&value!=='refused'&&a.id==='refusal_reviewed')&&!(r.id==='REPLY_OPPORTUNITY_REVIEW'&&stage==='P16'&&a.id==='reply_received')&&!(r.id==='REPLY_OPPORTUNITY_REVIEW'&&['unknown','extension_requested'].includes(value)&&a.id==='opportunity_complete'))}
function compute(){let node='P01',seen=new Set(),trace=[];while(node!=='P18'){if(seen.has(node))return{kind:'error',message:'Invalid workflow loop',trace};seen.add(node);let q=Q.find(x=>x.id===node);if(!q)return{kind:'error',message:'Unsupported stage '+node,trace};if(!answers[node])return{kind:'question',q,trace};let opt=q.opts.find(o=>o.value===answers[node]);if(!opt)return{kind:'error',message:'Invalid answer',trace};trace.push(node);if(REV[opt.next]){let r=REV[opt.next],d=decisions[node],available=validActions(r,node,opt.value);if(d&&d.trigger===opt.value){let a=available.find(x=>x.id===d.action);if(a&&d.confirmed&&a.target!=='OUTCOME'&&a.target!=='EDIT'){node=nextOf(a.target,node);continue}if(a&&d.confirmed&&a.target==='OUTCOME')return{kind:'outcome',r,q,action:a,trace};}return{kind:'review',r,q,original:opt,actions:available,trace}}node=opt.next}return{kind:'handoff',trace}}
function renderStageNav(res){let active=res.q?.id||res.trace[res.trace.length-1]||'P01';$('g-stages').innerHTML=Q.map(q=>'<li class="'+(q.id===active?'active':res.trace.includes(q.id)?'complete':'')+'">'+safe(q.id)+' · '+safe(q.prompt.slice(0,57))+'</li>').join('');$('g-current').textContent=res.kind==='handoff'?'P18 HANDOFF':safe(active);$('g-progress').textContent=res.trace.length+' stage(s) reviewed · Synthetic demonstration'}
function help(res){let extra=res.r?'<h3>'+safe(res.r.title)+'</h3><p>'+safe(res.r.issue)+'</p><ul>'+res.r.checks.map(c=>'<li>'+safe(c)+'</li>').join('')+'</ul>':'<p>Select a response to see the relevant legal considerations.</p>';const q=res.q;const law=q?.law?'<h3>Applicable framework to verify</h3><p>'+safe(q.law)+'</p>':'';$('g-help').innerHTML=extra+law+'<h3>Legal controls</h3><p>Resolve facts and jurisdiction under the governing law. No admission, guilt, credibility finding or ex-parte ruling is automatic.</p>'}
function changeAnswerForm(q){const existing=answers[q.id];return '<details class="g-edit"><summary>Correct this answer here (no back navigation)</summary><p class="g-mini">Changing it clears dependent stage answers and their review confirmations.</p><label for="g-correction">Corrected response</label><div><select id="g-correction">'+q.opts.map(o=>'<option value="'+safe(o.value)+'" '+(o.value===existing?'selected':'')+'>'+safe(o.label)+'</option>').join('')+'</select> <button class="g-btn secondary" id="g-correct" type="button">Update response</button></div></details>'}
function render(){const res=compute();questionTrace=res.trace||[];renderStageNav(res);help(res);
if(res.kind==='error'){$('g-body').innerHTML='<div class="g-alert">'+safe(res.message)+'</div><button class="g-btn" id="g-reset-inline">Restart safely</button>';return}
if(res.kind==='handoff'){$('g-body').innerHTML='<h2>Initial inquiry route completed</h2><div class="g-success"><strong>Next: P18 — Inquiry Issue Identification</strong><p>The source Alpha 3.1 implementation ends here. This is a documented handoff, not permission to skip the remainder of the statutory inquiry.</p></div><div class="g-button-row"><button class="g-btn secondary" id="g-reset-inline">Start another scenario</button></div>';return}
const q=res.q;
if(res.kind==='question'){$('g-body').innerHTML='<h2>'+safe(q.prompt)+'</h2><p>Choose one fictional situation. No real names or case particulars are requested.</p><div class="g-choices">'+q.opts.map(o=>'<button type="button" class="g-choice" data-answer="'+safe(o.value)+'">'+safe(o.label)+'</button>').join('')+'</div>';return}
if(res.kind==='outcome'){$('g-body').innerHTML='<h2>'+safe(res.r.title)+'</h2><div class="g-success"><h3>Alternative procedural route</h3><p>'+safe(res.action.label)+'</p><p>No ordinary inquiry progression is presumed. Appropriate statutory action or referral remains for the competent authority.</p></div>'+changeAnswerForm(q)+'<div class="g-button-row"><button class="g-btn secondary" id="g-reset-inline">Try another scenario</button></div>';return}
const r=res.r,key=q.id+':'+res.original.value+':'+r.id;if(lastKey!==key){status='no';chosenAction='';checked=new Set();lastKey=key}
let available=res.actions;
let optionBlock=status==='yes'?'<h3>Choose the legally reviewed outcome</h3>'+available.map(a=>'<label class="g-action"><input type="radio" name="g-action-choice" value="'+safe(a.id)+'" '+(chosenAction===a.id?'checked':'')+'><span>'+safe(a.label)+'</span></label>').join(''):'';
let selected=available.find(a=>a.id===chosenAction);
let checklist=status==='yes'&&selected&&selected.target!=='EDIT'?'<h3>Confirm each required review item</h3><p class="g-mini">For this fictional example only. These checkmarks do not establish real legal compliance.</p>'+r.checks.map((c,i)=>'<label class="g-check"><input type="checkbox" data-check="'+i+'" '+(checked.has(i)?'checked':'')+'><span>'+safe(c)+'</span></label>').join(''):'';
let actionButton=status==='yes'&&selected?'<button class="g-btn" type="button" id="g-proceed" '+(selected.target!=='EDIT'&&checked.size!==r.checks.length?'disabled':'')+'>'+(selected.target==='OUTCOME'?'View alternative lawful route':selected.target==='EDIT'?'Change originating answer':'Proceed to next permitted step')+'</button>':'';
let noInfo=status!=='yes'?'<div class="g-soft"><h3>What should happen now?</h3><ul>'+r.checks.map(c=>'<li>'+safe(c)+'</li>').join('')+'</ul><p>After completing the required steps, choose <b>Yes</b> above and document which conditions were verified. You can change the original answer on this page as facts become clear.</p></div>':'';
$('g-body').innerHTML='<h2>'+safe(q.prompt)+'</h2><p>Recorded fictional answer: <strong>'+safe(res.original.label)+'</strong></p><div class="g-review"><span class="g-label">Review and correction · '+safe(q.id)+'</span><h3>'+safe(r.title)+'</h3><p class="g-review-note">'+safe(r.issue)+'</p></div><h3>Has this issue been resolved now?</h3><div class="g-status" role="group" aria-label="Resolution status"><button class="g-toggle" data-status="yes" aria-pressed="'+(status==='yes')+'">Yes</button><button class="g-toggle" data-status="no" aria-pressed="'+(status==='no')+'">No</button><button class="g-toggle" data-status="unsure" aria-pressed="'+(status==='unsure')+'">Not sure</button></div>'+noInfo+optionBlock+checklist+'<div class="g-button-row">'+actionButton+'</div>'+changeAnswerForm(q);
}
function resetTo(target,mods){answers={};decisions={};status='no';chosenAction='';checked=new Set();lastKey='';for(const q of Q){if(Number(q.id.slice(1))>=Number(target.slice(1)))break;if(DEFAULT[q.id])answers[q.id]=DEFAULT[q.id]}Object.assign(answers,Object.fromEntries(Object.entries(mods).filter(([stage])=>Number(stage.slice(1))<Number(target.slice(1)))));render()}
$('g-scenario').innerHTML=EXAMPLES.map(([id,title])=>'<option value="'+safe(id)+'">'+safe(title)+'</option>').join('');
$('g-scenario').addEventListener('change',e=>{let row=EXAMPLES.find(x=>x[0]===e.target.value)||EXAMPLES[0];resetTo(row[2],row[3])});
$('g-restart').addEventListener('click',()=>{let row=EXAMPLES.find(x=>x[0]===$('g-scenario').value)||EXAMPLES[0];resetTo(row[2],row[3])});
$('g-body').addEventListener('click',e=>{const t=e.target;
if(t.id==='g-reset-inline'){ $('g-scenario').value='manual';resetTo('P01',{});return}
if(t.dataset.answer){let s=compute().q?.id;if(!s)return;let pos=Number(s.slice(1));for(const k of Object.keys(answers))if(Number(k.slice(1))>=pos)delete answers[k];for(const k of Object.keys(decisions))if(Number(k.slice(1))>=pos)delete decisions[k];answers[s]=t.dataset.answer;lastKey='';render();return}
if(t.dataset.status){status=t.dataset.status;chosenAction='';checked=new Set();render();return}
if(t.id==='g-correct'){let s=compute().q?.id;let correction=$('g-correction')?.value;if(!s||!Q.find(x=>x.id===s)?.opts.some(o=>o.value===correction))return;let pos=Number(s.slice(1));for(const k of Object.keys(answers))if(Number(k.slice(1))>=pos)delete answers[k];for(const k of Object.keys(decisions))if(Number(k.slice(1))>=pos)delete decisions[k];answers[s]=correction;lastKey='';render();return}
if(t.id==='g-proceed'){const r=compute();if(r.kind!=='review'||status!=='yes')return;const a=r.actions.find(x=>x.id===chosenAction);if(!a)return;if(a.target==='EDIT'){const edit=$('g-correction');if(edit){edit.focus();edit.scrollIntoView({block:'center',behavior:'smooth'})}return}if(checked.size!==r.r.checks.length)return;decisions[r.q.id]={trigger:r.original.value,action:a.id,confirmed:true};lastKey='';render();return}
});
$('g-body').addEventListener('change',e=>{let t=e.target;if(t.name==='g-action-choice'){chosenAction=t.value;checked=new Set();render();return}if(t.dataset.check!==undefined){const i=Number(t.dataset.check);if(t.checked)checked.add(i);else checked.delete(i);let b=$('g-proceed');if(b)b.disabled=checked.size!==(compute().r?.checks.length||0)}});resetTo('P01',{});
})();